import json

import pprint


class Node:
    def __init__(self, value):
        self.value = value
    def print_status(self):
        print(self.value.to_string())

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def greet(self):
        print(f"Person greeting {self.name} with {self.age}.")

class Game(Node):
    def __init__(self, name, board):
        node = Person(name, age)
        self.board = board
        self.state = node.print_status()
    def reset(self):
        self.board = []
